    seen=[[False]*w for _ in range(h)]; best=None
    import itertools
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j]; cells=[(i,j)]; st={(i,j)}
                while st:
                    x,y=st.pop()
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<h and 0<=b<w and g[a][b]==col and not (a,b) in st:
                                st.add((a,b))
                cells.extend(st)
                # distance 1 (chebyshev) from any cell of this object
                new=set()
                for x,y in cells:
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<h and 0<=b<w and g[a][b]==0:
                                new.add((a,b))
                if best is None or len(new)<best[0]:
                    best=(len(new),col,new)
    print(best)
    if best:
        for (x,y) in best[2]: out[x][y]=best[1]
    return out
